-- RentRoomBcn: esquema + datos iniciales. Ejecutar en Supabase > SQL Editor (idempotente).

create table if not exists public.flats (
  flat_id        text primary key,
  title          text not null,
  street         text,
  "mapImage"     text,
  neighborhood   text,
  city           text default 'Barcelona',
  "postalCode"   text,
  available      boolean not null default true
);

create table if not exists public.rooms (
  id                 bigint generated by default as identity primary key,
  slug               text not null unique,
  name               text not null,
  "imageSrc"         text,
  "imageAlt"         text,
  flat_id            text not null references public.flats(flat_id) on update cascade,
  available          boolean not null default true,
  status             text not null default 'available' check (status in ('available', 'soon')),
  "metaTitle"        text,
  "metaDescription"  text
);

create index if not exists rooms_flat_id_idx on public.rooms (flat_id);

-- Row Level Security: lectura pública, escritura solo usuarios autenticados
alter table public.flats enable row level security;
alter table public.rooms enable row level security;

drop policy if exists "flats public read" on public.flats;
drop policy if exists "rooms public read" on public.rooms;
drop policy if exists "flats auth write" on public.flats;
drop policy if exists "rooms auth write" on public.rooms;

create policy "flats public read" on public.flats for select using (true);
create policy "rooms public read" on public.rooms for select using (true);
create policy "flats auth write" on public.flats for all to authenticated using (true) with check (true);
create policy "rooms auth write" on public.rooms for all to authenticated using (true) with check (true);

